SELECT last_restock_cohort, store_id, cnt FROM (SELECT CASE WHEN YEAR(last_restock) < 2024 THEN 'before_2024' WHEN YEAR(last_restock) = 2024 THEN '2024' ELSE 'after_2024' END AS last_restock_cohort, store_id, COUNT(*) AS cnt FROM inventory WHERE last_restock <= '2024-08-31' GROUP BY CASE WHEN YEAR(last_restock) < 2024 THEN 'before_2024' WHEN YEAR(last_restock) = 2024 THEN '2024' ELSE 'after_2024' END, store_id) AS sub WHERE cnt >= 9 ORDER BY cnt DESC;
